window.GW_GHOST_PRE["as"] = {"gc_deception_simple":"পেজটোৱে আনৰ সফলতাক প্ৰমাণ হিচাপে ব্যৱহাৰ কৰিছিল, বা আপোনাক কথাটো গোপন কৰি ৰাখিবলৈ কৈছিল।","gc_unverified_simple":"GHOSTWALK এ এই পৰ্যবেক্ষণ লিপিবদ্ধ কৰিছে, কিন্তু ইয়াৰ বাবে এতিয়াও সাধাৰণ ভাষাৰ ব্যাখ্যা নাই।","gc_unverified_why":"পৰ্যবেক্ষণটো প্ৰমাণ হিচাপে লিপিবদ্ধ কৰা হৈছে। ইয়াক আৰু পৰীক্ষা কৰা হোৱা নাছিল, গতিকে ইয়াৰ পৰা কোনো ধৰণৰ সিদ্ধান্ত লোৱা উচিত নহয়।","gc_unverified_next":"ইয়াৰ বাবে কোনো ব্যক্তিগত তথ্য ধন পৰিশোধ বা শ্বেয়াৰ নকৰিব। পৰীক্ষা পুনৰায় চলাওক, বা সংস্থাটো স্বতন্ত্ৰভাৱে পৰীক্ষা কৰক।","allSet":"সকলো ছেট। মই ইয়াত চুকত থাকিম — যিকোনো সময়তে সহায়ৰ প্ৰয়োজন হ’লে মোক টেপ কৰক।","voiceNA":"এই ডিভাইচত এই ভাষাৰ বাবে ভইচ গাইডেন্স উপলব্ধ নহয়। টেক্সট গাইডেন্স অব্যাহত থাকিব।","g_check":"সন্দেহজনক বাৰ্তাটো ইয়াত পেষ্ট কৰক, বা আপল'ড বিকল্প ব্যৱহাৰ কৰক যদি আপুনি ইয়াক এটা স্ক্ৰীণশ্বট বা দস্তাবেজ হিচাপে লাভ কৰিছে। পাছৱৰ্ড, অ’টিপি বা বেংকিং প্ৰমাণপত্ৰ অন্তৰ্ভুক্ত নকৰিব। এবাৰ বিষয়বস্তু সাজু হ’লে তলৰ বিশ্লেষণ বুটামটো নিৰ্বাচন কৰক।","g_walk":"যদি কোনোবাই সন্দেহজনক বিনিয়োগৰ লিংক পঠিয়াইছে তেন্তে সেইটো খুলি নোযোৱাকৈ কপি কৰি এই বাকচটোত পেষ্ট কৰক। যেতিয়া আপুনি সাজু হ’ব, তেতিয়া “তদন্ত আৰম্ভ কৰক” নিৰ্বাচন কৰক। GHOSTWALK এ গন্তব্যস্থানটো পৃথকে পৰীক্ষা কৰিবলৈ চেষ্টা কৰিব আৰু ই পৰ্যবেক্ষণ কৰা আচৰণ ঘূৰাই দিব।","g_qr":"সম্পূৰ্ণ QR ক'ড থকা এখন ফটো বা স্ক্ৰীণশ্বট নিৰ্বাচন কৰক। আপুনি ইয়াক পেমেণ্ট এপ্লিকেচন ব্যৱহাৰ কৰি স্কেন কৰাৰ প্ৰয়োজন নাই। ছবিখন নিৰ্বাচন কৰাৰ পিছত প্ৰিভিউটো পৰীক্ষা কৰক আৰু “এই ছবিখন ব্যৱহাৰ কৰক” বাছক।","g_trusted":"প্ৰথমে সাৰাংশটো পৰ্যালোচনা কৰক। যদি ই পৰিস্থিতিৰ সঠিক বৰ্ণনা কৰে, তেন্তে আপুনি জড়িত কৰিব বিচৰা বিশ্বাসযোগ্য ব্যক্তিজনক নিৰ্বাচন কৰক। GHOSTWALK এ তেওঁলোকৰ বাবে সতৰ্কবাণীৰ তথ্য প্ৰস্তুত কৰিব। পঠোৱাৰ আগতে পৰীক্ষা কৰক।","g_paid":"অতিৰিক্ত ধন প্ৰেৰণ নকৰিব। কি আৰু কেতিয়া দিয়া হৈছিল ৰেকৰ্ড কৰি আৰম্ভ কৰক। তাৰ পিছত স্ক্ৰীণশ্বট, পেমেণ্ট ৰেফাৰেন্স আৰু বাৰ্তাসমূহ সংৰক্ষণ কৰক। GHOSTWALK এ তথ্যসমূহ সংগঠিত কৰিব আৰু পৰৱৰ্তী সমৰ্থিত পুনৰুদ্ধাৰ পদক্ষেপসমূহ দেখুৱাব।","g_check_go":"ওপৰৰ বাৰ্তাটো টাইপ বা পেষ্ট কৰক, তাৰ পিছত বিশ্লেষণ আৰম্ভ কৰিবলৈ এই বুটাম টিপক। এই ডিভাইচত ভূতে সকলো পঢ়ে — একো খোলা বা ধন দিয়া নহয়।","g_walk_go":"এই বুটামটো টিপক ভূতটোক লিংকটোৰ তললৈ পঠিয়াবলৈ। ই ভুৱা বিৱৰণৰ সৈতে যাত্ৰা চাৰ্ভাৰ-পক্ষত খোজ কাঢ়ে আৰু নিৰাপদে ৰৈ যায় — আপুনি নিজে কেতিয়াও ইয়াক খোলা নহয়।","g_qr_go":"UPI বিৱৰণ পেষ্ট কৰাৰ পিছত এই বুটাম টিপক। ভূতে টকাখিনি ক’লৈ যাব সেইটো ডিকোড কৰি পেয়ী, পৰিমাণ আৰু সতৰ্কবাণী দেখুৱায়।","g_trusted_go":"সতৰ্কবাণী প্ৰস্তুত কৰিবলৈ এই বুটামটো টিপক। আপোনাৰ বিশ্বাসযোগ্য ব্যক্তিৰ সৈতে শ্বেয়াৰ কৰাৰ আগতে পূৰ্বদৰ্শন ভালদৰে পঢ়ক।","g_paid_go":"আপোনাৰ ঘটনা পেক নিৰ্মাণ কৰিবলৈ এই বুটাম টিপক। ই আপোনাৰ সময়ৰেখা আৰু 1930 হেল্পলাইনৰ বাবে প্ৰমাণ সংগঠিত কৰে — পুনৰুদ্ধাৰ কেতিয়াও নিশ্চিত নহয়।","m_done":"তদন্ত সম্পূৰ্ণ হৈছে। এটা এটাকৈ তথ্যবোৰ বুজাব পাৰো।","langChanged":"ভাষা সলনি হ’ল। এই ভাষাত মই আপোনাক পথ প্ৰদৰ্শন কৰি যাম।","voiceWelcome":"Ghostwalk লৈ আপোনাক স্বাগতম। মই তোমাক গাইড কৰিবলৈ আহিছো৷ মই প্ৰতিটো বিকল্প বুজাব পাৰো আৰু ইয়াৰ পিছত কি কৰিব লাগে দেখুৱাব পাৰো।","textWelcome":"GHOSTWALK লৈ আপোনাক স্বাগতম। সহায়ৰ প্ৰয়োজন হ’লে মই ইয়াত আছো৷ সৰু Ghost বা যিকোনো এটা টেপ কৰক ? এটা ব্যাখ্যাৰ বাবে আইকন।","hintHome":"সহায়ৰ প্ৰয়োজন? টেপ কৰক ? যিকোনো বিকল্পৰ কাষত, বা গাইড ভ্ৰমণৰ বাবে ভূত খুলিব।","vDoubt":"সন্দেহ হ’লে এতিয়াও ধন নিদিব। প্ৰথমে বিশ্বাস কৰা কোনোবা এজনৰ লগত কথা পাতক।","qrUploadSub":"QR ক'ড থকা ফটো বা স্ক্ৰীণশ্বট আপলোড কৰক। GHOSTWALK এ পেমেণ্ট আৰম্ভ নকৰাকৈয়ে ইয়াক ডিকোড কৰিব।","qrNoCode":"এই ছবিখনৰ পৰা আমি এটা QR ক’ড পঢ়িব পৰা নাছিলো। য'ত সমগ্ৰ QR ক'ড দেখা যায় তাত এটা স্পষ্ট ছবি চেষ্টা কৰক।","qrTooBig":"সেই ছবিখন বৰ ডাঙৰ। অনুগ্ৰহ কৰি 8 MB ৰ অন্তৰ্গত এটা ছবি বাছক।","qrBadFile":"সেই ফাইলটো ছবি হিচাপে পঢ়িব পৰা নগ’ল। অনুগ্ৰহ কৰি এটা PNG, JPG বা WebP স্ক্ৰীণশ্বট বাছক।","qrGuideSteps":"এটা নমুনা QR ছবি লোড কৰা হৈছে। ছবিৰ পূৰ্বদৰ্শন পৰ্যালোচনা কৰক। এই ছবি ব্যৱহাৰ কৰক নিৰ্ব্বাচন কৰক। GHOSTWALK এ এতিয়া ইয়াৰ বিষয়বস্তু ডিকোড কৰিব।","g_qr_img":"যদি কোনোবাই আপোনাক বিনিয়োগ বা পেমেণ্টৰ বাবে QR ক'ড পঠিয়াইছে, তেন্তে ছবিখন ইয়াত আপলোড কৰক। কেৱল ইয়াত কি আছে চাবলৈ আপুনি আপোনাৰ পেমেণ্ট এপ্লিকেচন ব্যৱহাৰ কৰি ইয়াক স্কেন কৰাৰ প্ৰয়োজন নাই। ডিকোড কৰাৰ পিছত আন কোনো কাম কৰাৰ আগতে গন্তব্যস্থানটো পৰ্যালোচনা কৰক।","g_qr_found":"ইয়াত QR ত কি কি আছে। একো দিয়া নহ’ল আৰু একো খোলা নহ’ল।","sampleQrNote":"নমুনা QR — কেৱল প্ৰদৰ্শন। কোনো ধৰণৰ পেমেণ্ট আৰম্ভ কৰা হোৱা নাছিল।","sampleCaseNote":"নমুনা পুনৰুদ্ধাৰ ক্ষেত্ৰ — কাল্পনিক ডেমো তথ্য। আৰোগ্য লাভৰ নিশ্চয়তা কেতিয়াও নহয়।","sampleAlertText":"মই এটা বিনিয়োগৰ অনুৰোধ পাইছিলোঁ যিটো GHOSTWALK-এ চিনাক্ত কৰিছিল যে ইয়াৰ অধিক পৰীক্ষণৰ প্ৰয়োজন। মই আগবাঢ়ি যোৱাৰ আগতে আপুনি মোৰ সৈতে এইটো পৰ্যালোচনা কৰিব পাৰিবনে?","resultsReady":"আপোনাৰ ফলাফল তলত সাজু হৈছে। মোক টেপ কৰক আৰু মই সহজভাৱে বুজাই দিম।","uncertain":"আমি এই কথা নিৰ্ভৰযোগ্যভাৱে পৰীক্ষা কৰিব পৰা নাছিলো। তাৰ অৰ্থ এইটো নহয় যে ই নিৰাপদ। অনুগ্ৰহ কৰি স্বতন্ত্ৰভাৱে পৰীক্ষা নকৰালৈকে আগবাঢ়ি নাযাব।","checking":"তলত চেক চলি আছে। ই গন্তব্যস্থানটো পৃথকে পৃথকে পঢ়ে, গতিকে আপুনি নিজে কোনো বস্তু স্পৰ্শ কৰিব নালাগে।","understood":"বুজি পাইছিল। মোৰ প্ৰয়োজন হ'লে মই ইয়াত আছো।","m_index":[null,null,"আপুনি কেৱল কেতিয়াও STOP বা NOT VERIFIED পায়। কেতিয়াও ভুৱা “নিৰাপদ” নহয়।"],"m_message":[null,null,"পিডিএফ টেবে ব্ৰ'চাৰ পঢ়ে। ভইচ টেবে আপোনাক টাইপ কৰাৰ পৰিৱৰ্তে কথা ক’বলৈ দিয়ে।"],"m_ghost":["সন্দেহজনক লিংকটো বাকচত পেষ্ট কৰক। নিজে খুলিব নালাগে।"],"m_recovery":[null,null,"আপোনাৰ বেংক আৰু হেল্পলাইনলৈ লৈ যাওক 1930. পৰৱৰ্তী সকলো পেমেণ্ট বন্ধ কৰক।"],"saidRed":"এইটোৱে STOP বুলি লিখা আছে। ধন নিদিব আৰু অ’টিপি বা বেংকৰ সবিশেষ শ্বেয়াৰ নকৰিব।","saidYellow":"ইয়াত লিখা আছে NOT VERIFIED। এতিয়াও ধন নিদিব।","ai_note":"এই তথ্যৰ ব্যাখ্যা দিবলৈ প্ৰয়োজনীয় তথ্যহে ভূতে লাভ কৰে। AI প্ৰচেছিঙৰ আগতে স্পৰ্শকাতৰ বিৱৰণ আঁতৰোৱা হয়।","ai_consent_q":"এই বিষয়বস্তু AI ব্যৱহাৰ কৰি ব্যাখ্যা কৰিবলে, GHOSTWALK এ ধৰা পৰা স্পৰ্শকাতৰ তথ্য আঁতৰোৱাৰ পিছত লিখনী প্ৰক্ৰিয়া কৰিব লাগিব। অব্যাহত ৰাখক?","ai_offtopic":"মই কেৱল GHOSTWALK, জালিয়াতি সুৰক্ষা আৰু বিনিয়োগকাৰী সুৰক্ষাৰ ক্ষেত্ৰত সহায় কৰো। বিনিয়োগ, শ্বেয়াৰ বা ট্ৰেডৰ পৰামৰ্শ দিব নোৱাৰো।","ai_missing_key":"এই ব্যাখ্যা আপোনাৰ ভাষাত এতিয়াও উপলব্ধ নহয়। GHOSTWALK ৰ আন প্ৰতিটো অংশই এতিয়াও কাম কৰে, আৰু ইয়াৰ পৰিৱৰ্তে তলৰ অন্তৰ্নিৰ্মিত উত্তৰটো সদায় দেখুওৱা হয়।","gd_red_simple":"GHOSTWALK এ তদন্ত কৰাৰ সময়ত নিৰ্দিষ্ট সতৰ্কবাণী চিন পৰ্যবেক্ষণ কৰিছিল। কিবা বিপজ্জনক কথা দেখা গ’ল, আৰু অধিক সতৰ্কবাণীৰ অনুপস্থিতি নিৰাপত্তাৰ প্ৰমাণ নহয়।","gd_red_why":"যিটো পৰ্যবেক্ষণ কৰা হৈছিল সেয়া প্ৰমাণ হিচাপে লিপিবদ্ধ কৰা হয়, প্ৰমাণিত আদালতৰ গোচৰ হিচাপে নহয়। বন্ধ কৰাটোক ন্যায্যতা প্ৰদান কৰাটো এতিয়াও যথেষ্ট, কাৰণ ধন পঠোৱা বা অ’টিপি শ্বেয়াৰ কৰাটো বাতিল কৰিব নোৱাৰি।","gd_red_next":"টকা পঠিয়াব নালাগে আৰু অ’টিপি, পিন, পাছৱৰ্ড বা কাৰ্ডৰ সুৰক্ষা ক’ড শ্বেয়াৰ নকৰিব। আন কোনো কাম কৰাৰ আগতে সংস্থাটোক স্বতন্ত্ৰভাৱে পৰীক্ষা কৰক, এই কথোপকথনৰ বাহিৰত।","gd_yellow_simple":"এই যাত্ৰাক বিশ্বাস কৰিব পৰাকৈ GHOSTWALK-এ যথেষ্ট প্ৰতিষ্ঠা কৰিব নোৱাৰিলে। তাৰ অৰ্থ এইটো নহয় যে ই নিৰাপদ, আৰু ইয়াৰ অৰ্থ এইটোও নহয় যে ই প্ৰৱঞ্চনামূলক।","gd_yellow_why":"পৰীক্ষা নকৰাৰ অৰ্থ হ’ল চেকসমূহে একো নিশ্চিত বা অস্বীকাৰ কৰিব নোৱাৰিলে। পৰীক্ষণ অবিহনে কাম কৰাৰ আশংকা সম্পূৰ্ণৰূপে আপোনাৰ ওপৰত পৰে।","gd_none_why":"এটা ব্যাখ্যাই কেৱল প্ৰকৃততে যিটো পৰ্যবেক্ষণ কৰা হৈছিল সেইটোহে বৰ্ণনা কৰিব পাৰে। চেক অবিহনে যিকোনো বৰ্ণনা অনুমানৰ কাম হ’ব।","gc_payment_destination_why":"পেমেণ্ট ঠিকনা হ’ল সেই ব্যক্তি বা ব্যৱসায় যিয়ে আপোনাৰ ধন লাভ কৰিব। যিহেতু ইয়াক স্বতন্ত্ৰভাৱে পৰীক্ষা কৰিব পৰা নগ’ল, সেয়েহে প্ৰকৃততে কোনে পেমেণ্ট লাভ কৰিব সেইটো নিশ্চিত কৰাৰ কোনো উপায় নাই।","gc_payment_destination_next":"এতিয়াও ধন নিদিব। আপুনি ইতিমধ্যে বিশ্বাস কৰা ৱেবছাইট বা ফোন নম্বৰ ব্যৱহাৰ কৰি আপোনাৰ পেমেণ্ট এপত দেখুওৱা পেয়ীৰ নামক অফিচিয়েল সংস্থাৰ নামৰ সৈতে তুলনা কৰক।","gc_withdrawal_trap_why":"বৈধভাৱে উলিওৱাৰ ফলত বাকী থকা ধনৰ পৰা চাৰ্জ কৰ্তন কৰা হয়। ধন মুকলি কৰাৰ আগতে নতুন পেমেণ্টৰ বাবে পৃথক দাবী এটা সুপৰিচিত ফান্দ, আৰু প্ৰথম পেমেণ্ট সাধাৰণতে কেতিয়াও ঘূৰাই দিয়া নহয়।","gc_withdrawal_trap_next":"পৰৱৰ্তী সকলো পেমেণ্ট বন্ধ কৰক। ধন মুকলি কৰাৰ উদ্দেশ্যে মাচুল, কৰ বা জমা ধন প্ৰেৰণ নকৰিব। ইতিমধ্যে পঠোৱা ধনখিনি হেৰাই যোৱা বুলি গণ্য কৰক আৰু লগে লগে আপোনাৰ বেংকৰ সৈতে যোগাযোগ কৰক।","gc_redirect_identity_why":"প্ৰতিটো হপ হৈছে আপুনি ক্লিক কৰা লিংকটোৰ বিষয়ে দৃশ্যমান একো সলনি নকৰাকৈ আপুনি দেখুওৱাটো সলনি কৰাৰ সুযোগ। আপুনি খুলিব বুলি ভবা সংগঠনটো হয়তো বেলেগ হ’ব পাৰে।","gc_redirect_identity_next":"যাত্ৰা বন্ধ কৰক আৰু এই পৃষ্ঠাত একো প্ৰৱেশ নকৰিব। আপুনি ইতিমধ্যে জনা ঠিকনা এটা টাইপ কৰি নিজেই অফিচিয়েল ৱেবছাইটটো খুলিব, তাৰ পিছত তাত অফাৰটো আছে নে নাই পৰীক্ষা কৰক।","gc_lookalike_address_next":"আগবাঢ়ি নাযাব। আপুনি ইতিমধ্যে বিশ্বাস কৰা এটা চেনেলৰ জৰিয়তে সংস্থাটোক পৰীক্ষা কৰক, যেনে আপোনাৰ বেংক কাৰ্ডৰ নম্বৰ বা ইয়াৰ অফিচিয়েল এপ। একেটা আড্ডাৰ ভিতৰত বা একেটা পৃষ্ঠাতে কেতিয়াও পৰীক্ষা নকৰিব।","gc_transport_security_why":"বৈধ প্ৰমাণপত্ৰ অবিহনে, যিয়েই সংযোগ চলায়, আপুনি যি টাইপ কৰে সেয়া পঢ়িব আৰু সলনি কৰিব পাৰে। এটা বেলেগ চাইটৰ নামকৰণ কৰা প্ৰমাণপত্ৰৰ অৰ্থ হ'ল পৃষ্ঠাটো ইয়াৰ অন্তৰ্গত নহয় ঠাইৰ পৰা সেৱা আগবঢ়োৱা হৈছে।","gc_transport_security_next":"কোনো ব্যক্তিগত বা আৰ্থিক তথ্য প্ৰৱেশ নকৰিব। পেজটো এৰি কেৱল সংস্থাটোৰ অফিচিয়েল এপ বা ৱেবছাইট ব্যৱহাৰ কৰক, যিটো স্বতন্ত্ৰভাৱে পোৱা যায়।","gc_credentials_request_why":"এটা OTP, পাছৱৰ্ড, পিন বা কাৰ্ড সুৰক্ষা ক'ডে পেমেণ্ট অনুমোদন কৰিব পাৰে বা কাৰোবাক আপোনাৰ একাউণ্টত প্ৰৱেশ দিব পাৰে। কোনো প্ৰকৃত সমৰ্থন প্ৰতিনিধিয়ে আপোনাক কেতিয়াও এটা শ্বেয়াৰ কৰিবলৈ কোৱা উচিত নহয়।","gc_credentials_request_next":"একো শ্বেয়াৰ নকৰিব। যদি আপুনি ইতিমধ্যে এটা OTP বা পাছৱৰ্ড দিছে, পাছৱৰ্ড সলনি কৰক আৰু আপোনাৰ বেংকলৈ তৎক্ষণাত ফোন কৰক, তাৰ পিছত চাইবাৰ-অপৰাধ হেল্পলাইনত ৰিপৰ্ট কৰক 1930.","gc_device_control_next":"অনুৰোধ নাকচ কৰক আৰু পৃষ্ঠাটো বন্ধ কৰক। আপুনি লগ নোপোৱা কোনোবা এজনৰ বাবে কেতিয়াও দূৰৱৰ্তী-প্ৰৱেশ চফ্টৱেৰ ইনষ্টল নকৰিব। যদি আপুনি ইতিমধ্যে ইয়াক ইনষ্টল কৰিছে, আপোনাৰ ইণ্টাৰনেট বন্ধ কৰক আৰু আপুনি বিশ্বাস কৰা কাৰোবাৰ পৰা সহায় বিচাৰক।","gc_app_install_next":"ইয়াক ইনষ্টল নকৰিব। ইতিমধ্যে ডাউনলোড কৰা যিকোনো বস্তু মচি পেলাওক, আৰু আপুনি সাধাৰণতে ব্যৱহাৰ কৰা ষ্ট'ৰৰ পৰা কেৱল ইয়াৰ অফিচিয়েল এপৰ জৰিয়তেহে সংস্থাটোৰ ওচৰলৈ যাওক।","gc_new_domain_why":"কেলেংকাৰী কাৰ্য্যকলাপ সাধাৰণতে দ্ৰুতভাৱে নিৰ্মাণ কৰা হয় আৰু দ্ৰুতভাৱে পৰিত্যাগ কৰা হয়। কোনো ইতিহাস নথকা ছাইট এটা নতুন হোৱাৰ সম্ভাৱনা মাত্ৰ স্থানান্তৰিত হোৱা এটা প্ৰতিষ্ঠিত সংস্থাতকৈ বহু বেছি।","gc_new_domain_next":"অফাৰটোক পৰীক্ষা নকৰা বুলি গণ্য কৰক। এই লিংক ব্যৱহাৰ নকৰাকৈয়ে আপুনি পাব পৰাকৈ সংস্থাটোৰ কোনো অফিচিয়েল ৱেবছাইট, এপ বা পঞ্জীয়ন আছে নে নাই পৰীক্ষা কৰক।","gc_pressure_why":"হেঁচা এনেদৰে ৰচনা কৰা হৈছে যাতে আপুনি বিশ্বাস কৰা কাৰোবাক চিন্তা কৰা বা সুধিব নোৱাৰে। কাইলৈ ​​এতিয়াও এটা প্ৰকৃত বিনিয়োগৰ সুযোগ আছে, কিন্তু কাউণ্টডাউন সাধাৰণতে নাথাকে।","gc_pressure_next":"ৰৈ ৰ’বা। পৃষ্ঠাটো বন্ধ কৰক, তাৰ পিছত আচলতে যিকোনো কাম কৰাৰ আগতে সংস্থাটোক স্বতন্ত্ৰভাৱে পৰীক্ষা কৰক।","gc_deception_next":"প্ৰশংসাপত্ৰৰ ওপৰত নিৰ্ভৰ নকৰিব। আপুনি বিশ্বাস কৰা কোনোবা এজনক অফাৰটো দেখুৱাওক, এই কথা-বতৰাৰ বাহিৰত, ইয়াৰ ওপৰত কাম কৰাৰ আগতে।","gc_off_channel_next":"কথোপকথনটো পুনৰ এটা অফিচিয়েল চেনেললৈ লৈ যাওক, বা বন্ধ কৰক। ব্যক্তিগত আড্ডা এপ্লিকেচনত আগবাঢ়ি নাযাব।","gc_escalation_why":"প্ৰকৃত বিনিয়োগে সদায় ৰিস্ক বহন কৰে আৰু কেতিয়াও লাভৰ নিশ্চয়তা নিদিয়ে। সৰুৰে পৰা আৰম্ভ কৰি তাৰ পিছত বৃদ্ধি হোৱা এটা আৰ্হি আপুনি হেৰুৱাবলৈ থিয় হৈ থকাখিনি বৃদ্ধি কৰিবলৈ ডিজাইন কৰা হৈছে।","gc_escalation_next":"পৰৱৰ্তী পেমেণ্ট নকৰিব। নিশ্চিত উভতি অহাটোৱেই হৈছে আটাইতকৈ স্পষ্ট সতৰ্কবাণী।","gc_unreachable_why":"নিৰ্ভৰযোগ্যভাৱে লোড নকৰা ঠিকনা এটা পৰীক্ষা কৰিব নোৱাৰি। সেয়া প্ৰমাণৰ অনুপস্থিতি, নিৰাপত্তাৰ প্ৰমাণ নহয়।","gc_unreachable_next":"অফাৰটোক অভেৰিফাইড বুলি গণ্য কৰক আৰু ধন নিদিব। ই আপোনাৰ বাবে কাম কৰিলে বুলি কোৱাৰ অৰ্থ এইটো নহয় যে ই নিৰাপদ।","gc_third_party_content_simple":"এই পৃষ্ঠাটো এটা ৱেবচাইট হিচাপে চলোৱা নহয়। ইয়াক বহু বাহিৰৰ সেৱাৰ পৰা চিলাই কৰা হয়।","gc_third_party_content_next":"এই পৃষ্ঠাত একো প্ৰৱেশ নকৰিব। সংস্থাটোৰ নিজৰ ৱেবছাইট বা এপৰ জৰিয়তে যোগাযোগ কৰক, যিটো স্বতন্ত্ৰভাৱে পোৱা যায়।"};
